"""Quote a short-hop fare in cents."""

def zone_cents(miles):
    if miles <= 2:
        return 250
    if miles <= 8:
        return 250 + (miles - 2) * 40
    return 490 + (miles - 8) * 25

def quote_fare(miles, riders):
    if riders < 1 or miles < 0:
        return 0
    return zone_cents(miles) * riders

"""Keep only the digits from a phone field."""

def digits_only(raw):
    chars = []
    for ch in str(raw):
        if ch.isdigit():
            chars.append(ch)
    return "".join(chars)

"""Format a grocery shelf card from aisle and bin."""

class ShelfCard:
    def __init__(self, aisle, bin_code):
        self.aisle = aisle
        self.bin_code = bin_code

    def line(self):
        return f"Aisle {self.aisle} / bin {self.bin_code}"

def format_shelf_card(aisle, bin_code):
    card = ShelfCard(aisle, bin_code)
    return card.line()

"""Map temperature and humidity to a work-rest band."""

def dew_penalty(humidity):
    if humidity < 40:
        return 0
    if humidity < 70:
        return 2
    return 5

def band_name(score):
    if score < 80:
        return "normal"
    if score < 90:
        return "caution"
    return "rest"

def work_rest_band(temp_f, humidity):
    if humidity < 0 or humidity > 100:
        return "unknown"
    return band_name(temp_f + dew_penalty(humidity))

"""Parking fee in cents from posted duration tiers."""

def parking_cents(minutes):
    if minutes <= 0:
        return 0
    tiers = ((30, 200), (60, 350), (120, 600))
    for limit, price in tiers:
        if minutes <= limit:
            return price
    extra = minutes - 120
    blocks = (extra + 59) // 60
    return 600 + blocks * 250

"""Move one step on a grid and stay inside the rectangle."""

def clamp_step(point, delta, bounds):
    x, y = point
    dx, dy = delta
    width, height = bounds
    nx = x + dx
    ny = y + dy
    if nx < 0:
        nx = 0
    elif nx >= width:
        nx = width - 1
    if ny < 0:
        ny = 0
    elif ny >= height:
        ny = height - 1
    return (nx, ny)

"""Mix two RGB triples with equal weight."""

MID_WEIGHT = 1
END_WEIGHT = 1

def mix_rgb(left, right):
    scale = MID_WEIGHT + END_WEIGHT
    mixed = []
    for a, b in zip(left, right):
        mixed.append((a * MID_WEIGHT + b * END_WEIGHT) // scale)
    return tuple(mixed)

"""Minutes shared by two shifts on the same day."""

def clip_span(start, end):
    if end < start:
        return (start, start)
    return (start, end)

def shared_minutes(a_start, a_end, b_start, b_end):
    a0, a1 = clip_span(a_start, a_end)
    b0, b1 = clip_span(b_start, b_end)
    begin = a0 if a0 > b0 else b0
    finish = a1 if a1 < b1 else b1
    if finish <= begin:
        return 0
    return finish - begin
